26	struct BFS_F {
27	  uintE* Parents;
28	  BFS_F(uintE* _Parents) : Parents(_Parents) {}
29	  inline bool update (uintE s, uintE d) { //Update
30	    if(Parents[d] == UINT_E_MAX) { Parents[d] = s; return 1; }
31	    else return 0;
32	  }
33	  inline bool updateAtomic (uintE s, uintE d){ //atomic version of Update
34	    return (CAS(&Parents[d],UINT_E_MAX,s));
35	  }
36	  //cond function checks if vertex has been visited yet
37	  inline bool cond (uintE d) { return (Parents[d] == UINT_E_MAX); }
38	};
39	
40	template <class vertex>
41	void Compute(graph<vertex>& GA, commandLine P) {
42	  long start = P.getOptionLongValue("-r",0);
43	  long n = GA.n;
44	  //creates Parents array, initialized to all -1, except for start
45	  uintE* Parents = newA(uintE,n);
46	  {parallel_for(long i=0;i<n;i++) Parents[i] = UINT_E_MAX;}
47	  Parents[start] = start;
48	
49	  vertexSubset Frontier(n,start); //creates initial frontier
50	  long rounds = 0;      //number of BFS levels
51	  long visited = 0;     //number of visited vertices
52	  while(!Frontier.isEmpty()){ //loop until frontier is empty
53	    rounds++;
54	    visited += Frontier.numNonzeros();
55	    vertexSubset output = edgeMap(GA, Frontier, BFS_F(Parents));
56	    Frontier.del();
57	    Frontier = output; //set new frontier
58	  }
59	  Frontier.del();
60	  cout << "BFS levels: " << rounds << endl;
61	  cout << "BFS visited: " << visited << endl;
62	  free(Parents);
63	}
