28	template <class vertex>
29	struct PR_F {
30	  double* p_curr, *p_next;
31	  vertex* V;
32	  PR_F(double* _p_curr, double* _p_next, vertex* _V) :
33	    p_curr(_p_curr), p_next(_p_next), V(_V) {}
34	  inline bool update(uintE s, uintE d){ //update function applies PageRank equation
35	    p_next[d] += p_curr[s]/V[s].getOutDegree();
36	    return 1;
37	  }
38	  inline bool updateAtomic (uintE s, uintE d) { //atomic Update
39	    writeAdd(&p_next[d],p_curr[s]/V[s].getOutDegree());
40	    return 1;
41	  }
42	  inline bool cond (intT d) { return cond_true(d); }
43	};
44	
45	//vertex map function to update its p value according to PageRank equation
46	struct PR_Vertex_F {
47	  double damping;
48	  double addedConstant;
49	  double* p_curr;
50	  double* p_next;
51	  PR_Vertex_F(double* _p_curr, double* _p_next, double _damping, long n) :
52	    p_curr(_p_curr), p_next(_p_next),
53	    damping(_damping), addedConstant((1-_damping)*(1/(double)n)){}
54	  inline bool operator () (uintE i) {
55	    p_next[i] = damping*p_next[i] + addedConstant;
56	    return 1;
57	  }
58	};
59	
60	//resets p
61	struct PR_Vertex_Reset {
62	  double* p_curr;
63	  PR_Vertex_Reset(double* _p_curr) :
64	    p_curr(_p_curr) {}
65	  inline bool operator () (uintE i) {
66	    p_curr[i] = 0.0;
67	    return 1;
68	  }
69	};
