25	// Exact triangle counting on a symmetric graph.
26	//
27	// Each triangle {a < b < c} is counted exactly once, at its lowest numbered
28	// vertex a: for every neighbor b of a with b > a we count the number of
29	// neighbors c of b with c > b and c in N(a).  The inner count is performed with
30	// the countOutNgh primitive, so the same code runs on both uncompressed and
31	// compressed (Ligra+) graphs.
32	#include "ligra.h"
33	#include "quickSort.h"
34	
35	// Materializes the out-neighbors of a vertex into a freshly allocated array.
36	// Uses copyOutNgh (which reports the index of each neighbor) so that it works
37	// for uncompressed as well as compressed vertices.
38	template <class vertex>
39	uintE* materializeOutNgh(vertex& v, uintE v_id, uintT d) {
40	  uintE* A = newA(uintE, d);
41	  auto f = [&] (uintE src, uintE ngh) { return ngh; };
42	  auto g = [&] (uintE ngh, uintT offset, uintE val) { A[offset] = val; };
43	  v.template copyOutNgh<uintE>(v_id, 0, f, g);
44	  return A;
45	}
46	
47	// Membership test in a sorted array of vertex ids.
48	inline bool inSortedNgh(uintE* A, uintT d, uintE key) {
49	  long lo = 0, hi = (long)d - 1;
50	  while (lo <= hi) {
51	    long mid = lo + ((hi - lo) >> 1);
52	    if (A[mid] == key) return true;
53	    if (A[mid] < key) lo = mid+1;
54	    else hi = mid-1;
55	  }
56	  return false;
57	}
58	
59	// Counts, for each vertex u, the number of triangles whose smallest vertex is u.
60	template <class vertex>
61	struct countTrianglesF {
62	  vertex* V;
63	  long* counts;
64	  countTrianglesF(vertex* _V, long* _counts) : V(_V), counts(_counts) {}
65	  inline bool operator () (uintE u) {
66	    uintT d_u = V[u].getOutDegree();
67	    if (d_u == 0) return 1;
68	    // N(u), sorted in increasing order.
69	    uintE* A = materializeOutNgh<vertex>(V[u], u, d_u);
70	    quickSort(A, d_u, less<uintE>());
71	    long ct = 0;
72	    for (uintT j = 0; j < d_u; j++) {
73	      uintE v = A[j];
74	      if (v > u) {
75	        // Count w in N(v) with w > v and w in N(u).
76	        auto pred = [&] (uintE v_id, uintE w) {
77	          return (w > v) && inSortedNgh(A, d_u, w);
78	        };
79	        ct += V[v].countOutNgh(v, pred);
80	      }
81	    }
82	    counts[u] = ct;
83	    free(A);
84	    return 1;
85	  }
86	};
87	
88	template <class vertex>
89	void Compute(graph<vertex>& GA, commandLine P) {
90	  long n = GA.n;
91	  long* counts = newA(long,n);
92	  {parallel_for(long i=0;i<n;i++) counts[i] = 0;}
93	
94	  // A frontier containing every vertex.
95	  bool* all = newA(bool,n);
96	  {parallel_for(long i=0;i<n;i++) all[i] = 1;}
97	  vertexSubset Frontier(n,n,all);
98	
99	  vertexMap(Frontier, countTrianglesF<vertex>(GA.V, counts));
100	
101	  long count = sequence::plusReduce(counts,n);
102	  cout << "triangle count = " << count << endl;
103	
104	  Frontier.del();
105	  free(counts);
106	}
