147	  // A vertexSubset from boolean array giving number of true values. Calculate
148	  // number of nonzeros and store in m.
149	 vertexSubsetData<pbbs::empty>(long _n, tuple<bool, pbbs::empty>* _d)
150	  : n(_n), s(NULL), d((bool*)_d), isDense(1)  {
151	    auto d_map = make_in_imap<size_t>(n, [&] (size_t i) { return get<0>(_d[i]); });
152	    auto f = [&] (size_t i, size_t j) { return i + j; };
153	    m = pbbs::reduce(d_map, f);
154	  }
155	
156	  void del() {
157	    if (d != NULL) free(d);
158	    if (s != NULL) free(s);
159	  }
160	
161	  // Sparse
162	  inline uintE& vtx(const uintE& i) const { return s[i]; }
163	  inline pbbs::empty vtxData(const uintE& i) const { return pbbs::empty(); }
164	  inline tuple<uintE, pbbs::empty> vtxAndData(const uintE& i) const { return make_tuple(s[i], pbbs::empty()); }
165	
166	  // Dense
167	  inline bool isIn(const uintE& v) const { return d[v]; }
168	  inline pbbs::empty ithData(const uintE& v) const { return pbbs::empty(); }
169	
170	  // Returns (uintE) -> Maybe<tuple<vertex, vertex-data>>.
171	  auto get_fn_repr() const {
172	    std::function<Maybe<tuple<uintE, pbbs::empty>>(const uintE&)> fn;
173	    if (isDense) {
174	      fn = [&] (const uintE& v) -> Maybe<tuple<uintE, pbbs::empty>> {
175	        auto ret = Maybe<tuple<uintE, pbbs::empty>>(make_tuple(v, pbbs::empty()));
176	        ret.exists = d[v];
177	        return ret;
178	      };
179	    } else {
180	      fn = [&] (const uintE& i) -> Maybe<tuple<uintE, pbbs::empty>> {
181	        return Maybe<tuple<uintE, pbbs::empty>>(make_tuple(s[i], pbbs::empty()));
182	      };
183	    }
184	    return fn;
185	  }
186	
187	  long size() { return m; }
188	  long numVertices() { return n; }
189	
190	  long numRows() { return n; }
191	  long numNonzeros() { return m; }
192	
193	  bool isEmpty() { return m==0; }
194	  bool dense() { return isDense; }
195	
196	  void toSparse() {
197	    if (s == NULL && m > 0) {
198	      auto _d = d;
199	      auto f = [&] (size_t i) { return _d[i]; };
200	      auto f_in = make_in_imap<bool>(n, f);
201	      auto out = pbbs::pack_index<uintE>(f_in);
202	      out.alloc = false;
203	      s = out.s;
204	      if (out.size() != m) {
205	        cout << "bad stored value of m" << endl;
206	        cout << "out.size = " << out.size() << " m = " << m << " n = " << n << endl;
207	        abort();
208	      }
209	    }
210	    isDense = false;
211	  }
212	
213	  // Converts to dense but keeps sparse representation if it exists.
214	  void toDense() {
215	    if (d == NULL) {
216	      d = newA(bool,n);
217	      {parallel_for(long i=0;i<n;i++) d[i] = 0;}
218	      {parallel_for(long i=0;i<m;i++) d[s[i]] = 1;}
219	    }
220	    isDense = true;
