15	// Class that handles implementation specific freeing of memory
16	// owned by the graph
17	struct Deletable {
18	public:
19	  virtual void del() = 0;
20	};
21	
22	template <class vertex>
23	struct Uncompressed_Mem : public Deletable {
24	public:
25	  vertex* V;
26	  long n;
27	  long m;
28	  void* allocatedInplace, * inEdges;
29	
30	  Uncompressed_Mem(vertex* VV, long nn, long mm, void* ai, void* _inEdges = NULL)
31	  : V(VV), n(nn), m(mm), allocatedInplace(ai), inEdges(_inEdges) { }
32	
33	  void del() {
34	    if (allocatedInplace == NULL)
35	      for (long i=0; i < n; i++) V[i].del();
36	    else free(allocatedInplace);
37	    free(V);
38	    if(inEdges != NULL) free(inEdges);
39	  }
40	};
