87	// Like edgeMapDense but iterates over out-edges of frontier vertices.
88	template <class data, class vertex, class VS, class F>
89	vertexSubsetData<data> edgeMapDenseForward(graph<vertex> GA, VS& vertexSubset, F &f, const flags fl) {
90	  using D = tuple<bool, data>;
91	  long n = GA.n;
92	  vertex *G = GA.V;
93	  if (should_output(fl)) {
94	    D* next = newA(D, n);
95	    auto g = get_emdense_forward_gen<data>(next);
96	    {parallel_for(long i=0;i<n;i++) { std::get<0>(next[i]) = 0; }}
97	    parallel_for (long i=0; i<n; i++) {
98	      if (vertexSubset.isIn(i)) {
99	        G[i].decodeOutNgh(i, f, g);
100	      }
101	    }
102	    return vertexSubsetData<data>(n, next);
103	  } else {
104	    auto g = get_emdense_forward_nooutput_gen<data>();
105	    parallel_for (long i=0; i<n; i++) {
106	      if (vertexSubset.isIn(i)) {
107	        G[i].decodeOutNgh(i, f, g);
108	      }
109	    }
110	    return vertexSubsetData<data>(n);
111	  }
112	}
