114	// Applies f to out-edges of frontier vertices using sparse iteration.
115	// Collects output edges, filters invalid ones, returns new vertex subset.
116	template <class data, class vertex, class VS, class F>
117	vertexSubsetData<data> edgeMapSparse(graph<vertex>& GA, vertex* frontierVertices, VS& indices,
118	        uintT* degrees, uintT m, F &f, const flags fl) {
119	  using S = tuple<uintE, data>;
120	  long n = indices.n;
121	  S* outEdges;
122	  long outEdgeCount = 0;
123	
124	  if (should_output(fl)) {
125	    // Scan the degrees to get a distinct slot in outEdges for every edge
126	    // incident on the frontier.
127	    uintT* offsets = degrees;
128	    outEdgeCount = sequence::plusScan(offsets, offsets, m);
129	    outEdges = newA(S, outEdgeCount);
130	    auto g = get_emsparse_gen<data>(outEdges);
131	    parallel_for (size_t i = 0; i < m; i++) {
132	      uintT v = indices.vtx(i), o = offsets[i];
133	      vertex vert = frontierVertices[i];
134	      vert.decodeOutNghSparse(v, o, f, g);
135	    }
136	  } else {
137	    auto g = get_emsparse_nooutput_gen<data>();
138	    parallel_for (size_t i = 0; i < m; i++) {
139	      uintT v = indices.vtx(i);
140	      vertex vert = frontierVertices[i];
141	      vert.decodeOutNghSparse(v, 0, f, g);
142	    }
143	  }
144	
145	  if (should_output(fl)) {
146	    S* nextIndices = newA(S, outEdgeCount);
147	    if (fl & remove_duplicates) {
148	      if (GA.flags == NULL) {
149	        GA.flags = newA(uintE, n);
150	        {parallel_for(long i=0;i<n;i++) { GA.flags[i]=UINT_E_MAX; }}
151	      }
152	      auto get_key = [&] (size_t i) -> uintE& { return std::get<0>(outEdges[i]); };
153	      remDuplicates(get_key, GA.flags, outEdgeCount, n);
154	    }
155	    // Pack out the edges that were not written (marked with UINT_E_MAX).
156	    auto p = [] (tuple<uintE, data>& v) { return std::get<0>(v) != UINT_E_MAX; };
157	    size_t nextM = pbbs::filterf(outEdges, nextIndices, outEdgeCount, p);
158	    free(outEdges);
159	    return vertexSubsetData<data>(n, nextM, nextIndices);
160	  } else {
161	    return vertexSubsetData<data>(n);
162	  }
163	}
