299	// Packs out adjacency lists of vertices in vs, keeping neighbors where p(ngh) is true.
300	template <class vertex, class P>
301	vertexSubsetData<uintE> packEdges(graph<vertex>& GA, vertexSubset& vs, P& p, const flags& fl=0) {
302	  using S = tuple<uintE, uintE>;
303	  vs.toSparse();
304	  vertex* G = GA.V; long m = vs.numNonzeros(); long n = vs.numRows();
305	  if (vs.size() == 0) {
306	    return vertexSubsetData<uintE>(n);
307	  }
308	  auto degrees = array_imap<uintT>(m);
309	  granular_for(i, 0, m, (m > 2000), {
310	    uintE v = vs.vtx(i);
311	    degrees[i] = G[v].getOutDegree();
312	  });
313	  long outEdgeCount = pbbs::scan_add(degrees, degrees);
314	  bool* bits = newA(bool, outEdgeCount);
315	  uintE* tmp1 = newA(uintE, outEdgeCount);
316	  uintE* tmp2 = newA(uintE, outEdgeCount);
317	  if (should_output(fl)) {
318	    S* outV = newA(S, vs.size());
319	    granular_for(i, 0, m, (m > 2000), {
320	      uintE v = vs.vtx(i);
321	      size_t offset = degrees[i];
322	      auto bitsOff = &(bits[offset]); auto tmp1Off = &(tmp1[offset]);
323	      auto tmp2Off = &(tmp2[offset]);
324	      size_t ct = G[v].packOutNgh(v, p, bitsOff, tmp1Off, tmp2Off);
325	      outV[i] = make_tuple(v, ct);
326	    });
327	    free(bits); free(tmp1); free(tmp2);
328	    return vertexSubsetData<uintE>(n, m, outV);
329	  } else {
330	    granular_for(i, 0, m, (m > 2000), {
331	      uintE v = vs.vtx(i);
332	      size_t offset = degrees[i];
333	      auto bitsOff = &(bits[offset]); auto tmp1Off = &(tmp1[offset]);
334	      auto tmp2Off = &(tmp2[offset]);
335	      G[v].packOutNgh(v, p, bitsOff, tmp1Off, tmp2Off);
336	    });
337	    free(bits); free(tmp1); free(tmp2);
338	    return vertexSubsetData<uintE>(n);
339	  }
340	}
