342	// Returns, for each vertex v in vs, the number of out-neighbors of v satisfying
343	// the predicate p. With the pack_edges flag the adjacency lists are packed in
344	// place instead (see packEdges).
345	template <class vertex, class P>
346	vertexSubsetData<uintE> edgeMapFilter(graph<vertex>& GA, vertexSubset& vs, P& p, const flags& fl=0) {
347	  vertex* G = GA.V;
348	  long m = vs.numNonzeros(); long n = vs.numRows();
349	  vs.toSparse();
350	  if (fl & pack_edges) {
351	    return packEdges<vertex, P>(GA, vs, p, fl);
352	  }
353	  if (vs.size() == 0) {
354	    return vertexSubsetData<uintE>(n);
355	  }
356	  using S = tuple<uintE, uintE>;
357	  if (should_output(fl)) {
358	    S* out = newA(S, m);
359	    granular_for(i, 0, m, (m > 2000), {
360	      uintE v = vs.vtx(i);
361	      size_t ct = G[v].countOutNgh(v, p);
362	      out[i] = make_tuple(v, ct);
363	    });
364	    return vertexSubsetData<uintE>(n, m, out);
365	  } else {
366	    granular_for(i, 0, m, (m > 2000), {
367	      uintE v = vs.vtx(i);
368	      G[v].countOutNgh(v, p);
369	    });
370	    return vertexSubsetData<uintE>(n);
371	  }
372	}
