396	// Applies f to each vertex in V.
397	template <class VS, class F, typename std::enable_if<
398	  std::is_same<VS, vertexSubset>::value, int>::type=0 >
399	void vertexMap(VS& V, F f) {
400	  size_t n = V.numRows(), m = V.numNonzeros();
401	  if(V.dense()) {
402	    parallel_for(long i=0;i<n;i++) {
403	      if(V.isIn(i)) {
404	        f(i);
405	      }
