// in all copies or substantial portions of the Software.
//
// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS
// OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF
// MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND
// NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE
// LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION
// OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION
// WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

// Betweenness centrality from a single source (Brandes' algorithm).
//
// The forward sweep is a BFS that also counts, for every vertex, the number of
// shortest paths from the source that reach it (NumPaths).  Every BFS frontier
// is remembered in Levels.  The backward sweep then walks the levels from the
// deepest one back to the source, accumulating dependency scores along the
// reverse of the BFS DAG.  As in Ligra, the dependency values are carried
// through the backward sweep pre-multiplied by 1/NumPaths, which turns the
// per-edge scaling of Brandes' recurrence into a single add per vertex; the
// scaling is undone in one final pass over the array.
#include "ligra.h"
#include <vector>
#include <cmath>
#include <limits>
#include <iomanip>

typedef double fType;

// Forward (BFS) phase: adds the path count of the source of an edge into the
// path count of its destination.  Returns true exactly when the destination
// had no paths before, i.e. when it should join the next frontier.
struct BC_F {
  fType* NumPaths;
  bool* Visited;
  BC_F(fType* _NumPaths, bool* _Visited) :
    NumPaths(_NumPaths), Visited(_Visited) {}
  inline bool update(uintE s, uintE d) { //Update
    fType oldV = NumPaths[d];
    NumPaths[d] += NumPaths[s];
    return oldV == 0.0;
  }
  inline bool updateAtomic(uintE s, uintE d) { //atomic Update, basically an add
    volatile fType oldV, newV;
    do {
      oldV = NumPaths[d]; newV = oldV + NumPaths[s];
    } while(!CAS(&NumPaths[d],oldV,newV));
    return oldV == 0.0;
  }
  //only vertices that have not been reached by the BFS yet are of interest
  inline bool cond(uintE d) { return Visited[d] == 0; }
};

// Backward phase: same add-and-report-whether-it-was-zero pattern as BC_F, but
// on the dependency scores instead of the path counts.
struct BC_Back_F {
  fType* Dependencies;
  bool* Visited;
  BC_Back_F(fType* _Dependencies, bool* _Visited) :
    Dependencies(_Dependencies), Visited(_Visited) {}
  inline bool update(uintE s, uintE d) { //Update
    fType oldV = Dependencies[d];
    Dependencies[d] += Dependencies[s];
    return oldV == 0.0;
  }
  inline bool updateAtomic(uintE s, uintE d) { //atomic Update
    volatile fType oldV, newV;
    do {
      oldV = Dependencies[d]; newV = oldV + Dependencies[s];
    } while(!CAS(&Dependencies[d],oldV,newV));
    return oldV == 0.0;
  }
  //levels that have already been processed are excluded
  inline bool cond(uintE d) { return Visited[d] == 0; }
};

//vertex map function to mark the vertices of a new frontier as visited
struct BC_Vertex_F {
  bool* Visited;
  BC_Vertex_F(bool* _Visited) : Visited(_Visited) {}
  inline bool operator () (uintE i) {
    Visited[i] = 1;
    return 1;
  }
};

// Vertex map function used on the backward phase.  It closes off the level that
// is about to be pushed backwards (so that the following edgeMap cannot write
// into it, or into any deeper level) and adds this vertex' own 1/NumPaths term
// to its dependency score.
struct BC_Back_Vertex_F {
  bool* Visited;
  fType* Dependencies, *inverseNumPaths;
  BC_Back_Vertex_F(bool* _Visited, fType* _Dependencies, fType* _inverseNumPaths) :
    Visited(_Visited), Dependencies(_Dependencies),
    inverseNumPaths(_inverseNumPaths) {}
  inline bool operator () (uintE i) {
    Visited[i] = 1;
    Dependencies[i] += inverseNumPaths[i];
    return 1;
  }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  long start = P.getOptionLongValue("-r",0);
  const long n = GA.n;

  //number of shortest paths from start to each vertex
  fType* NumPaths = newA(fType,n);
  {parallel_for(long i=0;i<n;i++) NumPaths[i] = 0.0;}
  NumPaths[start] = 1.0;

  bool* Visited = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) Visited[i] = 0;}
  Visited[start] = 1;

  // Levels[r] is the set of vertices at BFS distance r from start.  The
  // frontiers are owned by this vector: they are read again by the backward
  // sweep and freed in a single pass at the end, so that no vertexSubset is
  // deleted twice (and any array that edgeMap materializes inside a frontier,
  // e.g. its dense representation, is freed too).
  vector<vertexSubset> Levels;
  Levels.push_back(vertexSubset(n,start));

  long round = 0;
  while(!Levels[round].isEmpty()) {
    round++;
    //accumulate path counts into the next frontier
    vertexSubset output = edgeMap(GA, Levels[round-1], BC_F(NumPaths,Visited));
    vertexMap(output, BC_Vertex_F(Visited));
    Levels.push_back(output);
  }
  //Levels[round] is the empty frontier that terminated the BFS

  fType* Dependencies = newA(fType,n);
  {parallel_for(long i=0;i<n;i++) Dependencies[i] = 0.0;}

  //invert NumPaths in place; unreachable vertices become infinite
  fType* inverseNumPaths = NumPaths;
  {parallel_for(long i=0;i<n;i++) inverseNumPaths[i] = 1/inverseNumPaths[i];}

  //Visited is reused by the backward sweep to mark the levels already done
  {parallel_for(long i=0;i<n;i++) Visited[i] = 0;}

  //the backward sweep follows edges against their forward direction
  GA.transpose();

  for(long r=round-1;r>=0;r--) {
    vertexMap(Levels[r], BC_Back_Vertex_F(Visited,Dependencies,inverseNumPaths));
    //level 0 holds only start, whose score is not propagated any further
    if(r > 0) {
      edgeMap(GA, Levels[r], BC_Back_F(Dependencies,Visited), GA.m/20, no_output);
    }
  }

  //undo the 1/NumPaths scaling to obtain the dependency scores
  {parallel_for(long i=0;i<n;i++) {
    //a vertex the BFS never reached lies on no shortest path at all, and its
    //infinite inverseNumPaths would otherwise produce a NaN here
    Dependencies[i] = (inverseNumPaths[i] == numeric_limits<fType>::infinity())
      ? 0.0
      : (Dependencies[i]-inverseNumPaths[i])/inverseNumPaths[i];
  }}

  fType maxScore = sequence::reduce<fType>(Dependencies,n,maxF<fType>());
  fType sum = sequence::plusReduce(Dependencies,n);
  cout << "BC rounds: " << round << endl;
  cout << setprecision(10) << "BC max score: " << maxScore << endl;
  cout << setprecision(10) << "BC sum: " << sum << endl;

  for(long i=0;i<=round;i++) Levels[i].del();
  free(Dependencies); free(Visited); free(inverseNumPaths);
}

