cd /tmp && cat > bcref2.py <<'EOF'
from collections import deque
toks=open('/workspace/inputs/rMatGraph_J_5_100').read().split()
n=int(toks[1]); m=int(toks[2])
offs=[int(x) for x in toks[3:3+n]]
edges=[int(x) for x in toks[3+n:3+n+m]]
adj=[edges[offs[i]:(offs[i+1] if i+1<n else m)] for i in range(n)]
for src in [0,1,3,7,42,127]:
    sigma=[0.0]*n; dist=[-1]*n; delta=[0.0]*n
    sigma[src]=1.0; dist[src]=0
    order=[]; preds=[[] for _ in range(n)]
    q=deque([src])
    while q:
        v=q.popleft(); order.append(v)
        for w in adj[v]:
            if dist[w]<0: dist[w]=dist[v]+1; q.append(w)
            if dist[w]==dist[v]+1: sigma[w]+=sigma[v]; preds[w].append(v)
    for w in reversed(order):
        for v in preds[w]: delta[v]+=(sigma[v]/sigma[w])*(1.0+delta[w])
    print("src=%d rounds=%d max=%.10g sum=%.10g"%(src,max(dist)+1,max(delta),sum(delta)))
EOF
python3 bcref2.py; echo "=== ligra BC ==="; for r in 0 1 3 7 42 127; do echo "-- src=$r"; (cd /workspace/apps && ./BC -r $r -s -rounds 0 ../inputs/rMatGraph_J_5_100); done
